class Solution:
    def minLength(self, s: str) -> int:
        """
        The problem asks for the minimum length of a string after repeatedly removing 
        substrings "AB" or "CD". Since removing a substring can create new "AB" or "CD" 
        substrings, a stack-based approach is ideal. We iterate through the string 
        character by character, pushing characters onto a stack. If the current 
        character and the top of the stack form "AB" or "CD", we pop the stack.
        """
        stack = []
        for char in s:
            if not stack:
                stack.append(char)
                continue

            # Check if the current character forms "AB" or "CD" with the top of the stack
            if (stack[-1] == 'A' and char == 'B') or (stack[-1] == 'C' and char == 'D'):
                stack.pop()
            else:
                stack.append(char)

        return len(stack)

