import math

class Solution:
    def canTraverseAllPairs(self, nums: list[int]) -> bool:
        """
        The problem asks if all indices in the array are connected in a graph where
        an edge exists between i and j if gcd(nums[i], nums[j]) > 1.
        This is equivalent to checking if all elements belong to a single connected component.

        Instead of building a graph of indices (which could have O(N^2) edges),
        we can use a Disjoint Set Union (DSU) to group numbers based on their prime factors.
        If two numbers share a prime factor, they are connected.
        """
        n = len(nums)
        if n == 1:
            return True

        # If any number is 1, it cannot be connected to any other number (gcd(1, x) = 1).
        # Since n > 1, if there's a 1, it's impossible to traverse all pairs.
        for x in nums:
            if x == 1:
                return False

        # DSU structure to manage connected components of indices.
        # However, it's more efficient to manage components of prime factors and numbers.
        # Let's use DSU on the indices of the nums array.
        parent = list(range(n))

        def find(i):
            if parent[i] == i:
                return i
            parent[i] = find(parent[i])
            return parent[i]

        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                parent[root_i] = root_j
                return True
            return False

        # To connect indices efficiently, we map each prime factor to the first index 
        # that we encountered which is divisible by that prime.
        prime_to_index = {}

        # Precompute primes using a sieve up to the maximum value in nums (10^5)
        # to speed up factorization.
        max_val = 100001
        min_prime = list(range(max_val))
        for i in range(2, int(max_val**0.5) + 1):
            if min_prime[i] == i:
                for j in range(i*i, max_val, i):
                    if min_prime[j] == j:
                        min_prime[j] = i

        # For each number in nums, find its prime factors and union its index
        # with the index of the first number that shared that prime factor.
        for i, val in enumerate(nums):
            temp = val
            while temp > 1:
                p = min_prime[temp]
                if p in prime_to_index:
                    union(i, prime_to_index[p])
                else:
                    prime_to_index[p] = i
                # Divide out all occurrences of this prime factor
                while temp % p == 0:
                    temp //= p

        # After processing all numbers, check if all indices belong to the same component.
        root = find(0)
        for i in range(1, n):
            if find(i) != root:
                return False

        return True

