from typing import List

class Solution:
    def countBeautifulPairs(self, nums: List[int]) -> int:
        """
        Counts the number of beautiful pairs (i, j) where 0 <= i < j < len(nums)
        and the first digit of nums[i] is coprime with the last digit of nums[j].
        """
        def get_first_digit(n: int) -> int:
            # Convert to string to easily get the first digit
            return int(str(n)[0])

        def get_last_digit(n: int) -> int:
            # Use modulo to get the last digit
            return n % 10

        def gcd(a: int, b: int) -> int:
            # Standard Euclidean algorithm for GCD
            while b:
                a, b = b, a % b
            return a

        count = 0
        n = len(nums)

        # Iterate through all possible pairs (i, j) where 0 <= i < j < n
        for i in range(n):
            first_digit = get_first_digit(nums[i])
            for j in range(i + 1, n):
                last_digit = get_last_digit(nums[j])

                # Check if the first digit of nums[i] and last digit of nums[j] are coprime
                if math.gcd(first_digit, last_digit) == 1:
                    count += 1

        return count

