class Solution:
    def minimumChanges(self, s: str, k: int) -> int:
        n = len(s)

        # Precompute the cost to make any substring s[i:j] a semi-palindrome.
        # cost[i][j] will store the minimum changes for substring s[i:j+1].
        # Since n is small (up to 200), we can use a 2D array.
        cost = [[float('inf')] * n for _ in range(n)]

        def get_semi_palindrome_cost(sub: str) -> int:
            m = len(sub)
            if m < 2:
                return float('inf') # Semi-palindrome must have 1 <= d < m

            min_changes = float('inf')
            # Try all possible divisors d such that 1 <= d < m and m % d == 0
            for d in range(1, m):
                if m % d == 0:
                    current_changes = 0
                    # For a given d, indices i and j are paired if:
                    # i % d == j % d AND (i // d + j // d) is related to the palindrome property.
                    # Actually, the definition says: "if we take indices that have the same modulo by d, 
                    # they form a palindrome."
                    # Let's group indices by their modulo d.
                    # For each group (indices with same modulo d), they must form a palindrome.
                    # The indices in group 'r' (0 <= r < d) are: r, r+d, r+2d, ..., r+(num_elements-1)d.
                    # This group forms a palindrome if sub[r + i*d] == sub[r + (num_elements-1-i)*d].

                    for r in range(d):
                        # Indices in this group: r, r+d, r+2d, ...
                        # Let's find the elements in this group.
                        group_indices = list(range(r, m, d))
                        num_elements = len(group_indices)
                        for idx in range(num_elements // 2):
                            if sub[group_indices[idx]] != sub[group_indices[num_elements - 1 - idx]]:
                                current_changes += 1
                    min_changes = min(min_changes, current_changes)
            return min_changes

        # Precompute all substring costs
        for i in range(n):
            for j in range(i + 1, n):
                # Substring is s[i:j+1]
                sub = s[i:j+1]
                cost[i][j] = get_semi_palindrome_cost(sub)

        # DP to find the minimum changes to partition s into k semi-palindromes.
        # dp[i][j] = min changes to partition s[0:j] into i semi-palindromes.
        # We want dp[k][n].

        dp = [[float('inf')] * (n + 1) for _ in range(k + 1)]
        dp[0][0] = 0

        for i in range(1, k + 1):
            for j in range(1, n + 1):
                # Try all possible split points p such that s[p:j] is the i-th substring.
                # The i-th substring is s[p:j], which corresponds to cost[p][j-1].
                # p must be at least i-1 because each substring must have length >= 2.
                # Wait, the problem says "semi-palindrome" requires 1 <= d < len.
                # This implies len >= 2.
                for p in range(i - 1, j):
                    # Substring is s[p:j], length is j-p.
                    # For semi-palindrome, j-p must be >= 2.
                    if j - p >= 2:
                        if dp[i-1][p] != float('inf') and cost[p][j-1] != float('inf'):
                            dp[i][j] = min(dp[i][j], dp[i-1][p] + cost[p][j-1])

        return int(dp[k][n])

