class Solution:
    def countOfPeaks(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        bit = [0] * (n + 1)

        def update_bit(idx, val):
            idx += 1
            while idx <= n:
                bit[idx] += val
                idx += idx & (-idx)

        def query_bit(idx):
            idx += 1
            s = 0
            while idx > 0:
                s += bit[idx]
                idx -= idx & (-idx)
            return s

        def is_peak(i):
            if i <= 0 or i >= n - 1:
                return False
            return nums[i] > nums[i-1] and nums[i] > nums[i+1]

        peak_status = [0] * n
        for i in range(1, n - 1):
            if is_peak(i):
                peak_status[i] = 1
                update_bit(i, 1)

        results = []
        for q in queries:
            if q[0] == 1:
                l, r = q[1], q[2]
                if l + 1 <= r - 1:
                    results.append(query_bit(r - 1) - query_bit(l))
                else:
                    results.append(0)
            else:
                idx, val = q[1], q[2]
                if nums[idx] == val:
                    continue

                # The peak status of idx-1, idx, and idx+1 can change.
                # We only care about indices i where 1 <= i < n-1.
                for i in range(idx - 1, idx + 2):
                    if 1 <= i < n - 1:
                        if peak_status[i] == 1:
                            update_bit(i, -1)
                            peak_status[i] = 0

                nums[idx] = val

                for i in range(idx - 1, idx + 2):
                    if 1 <= i < n - 1:
                        if is_peak(i):
                            peak_status[i] = 1
                            update_bit(i, 1)

        return results

class Solution:
    def clearDigits(self, s: str) -> str:
        """
        The problem asks us to remove all digits and their closest non-digit character to the left.
        This is a classic stack problem. We iterate through the string:
        - If the character is a digit, we pop the last character added to the stack (the closest non-digit to its left).
        - If the character is not a digit, we push it onto the stack.

        Since the problem guarantees that it's always possible to delete all digits, 
        we don't need to worry about popping from an empty stack (though in a real-world 
        scenario, we would check).
        """
        stack = []
        for char in s:
            if char.isdigit():
                # If it's a digit, remove the closest non-digit character to its left.
                # In our stack implementation, that's the top element.
                if stack:
                    stack.pop()
            else:
                # If it's a non-digit, add it to the stack.
                stack.append(char)

        # Join the remaining characters in the stack to form the resulting string.
        return "".join(stack)

