    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n = len(source)
        m = len(pattern)
        target_set = [False] * n
        for idx in targetIndices:
            target_set[idx] = True

        char_indices = [[] for _ in range(26)]
        for j, char in enumerate(source):
            char_indices[ord(char) - ord('a')].append(j)

        inf = float('inf')
        dp = [inf] * n

        # Base case: pattern[0]
        p0_idx = ord(pattern[0]) - ord('a')
        for j in char_indices[p0_idx]:
            dp[j] = 1 if target_set[j] else 0

        for i in range(1, m):
            new_dp = [inf] * n
            pi_idx = ord(pattern[i]) - ord('a')

            # Precompute prefix minimums of dp
            prefix_min_dp = [inf] * (n + 1)
            curr_m = inf
            for j in range(n):
                if dp[j] < curr_m:
                    curr_m = dp[j]
                prefix_min_dp[j+1] = curr_m

            for j in char_indices[pi_idx]:
                m_prev = prefix_min_dp[j]
                if m_prev != inf:
                    new_dp[j] = m_prev + (1 if target_set[j] else 0)
            dp = new_dp

        ans_min_used = min(dp)
        return len(targetIndices) - ans_min_used

