    def minFlips(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0])

        def get_row_flips():
            flips = 0
            for r in range(m):
                left = 0
                right = n - 1
                while left < right:
                    if grid[r][left] != grid[r][right]:
                        flips += 1
                    left += 1
                    right -= 1
            return flips

        def get_col_flips():
            flips = 0
            for c in range(n):
                top = 0
                bottom = m - 1
                while top < bottom:
                    if grid[top][c] != grid[bottom][c]:
                        flips += 1
                    top += 1
                    bottom -= 1
            return flips

        return min(get_row_flips(), get_col_flips())

