    def maxMoves(self, kx: int, ky: int, positions: List[List[int]]) -> int:
        """
        The problem asks for the total number of moves made by a knight capturing all pawns.
        Alice wants to maximize the total moves, Bob wants to minimize them.
        This is a minimax problem on a game tree, but since the number of pawns is small (up to 15),
        we can use dynamic programming with bitmasking.

        The state of the game can be represented by (current_knight_position, mask_of_remaining_pawns).
        However, the knight's position is always one of the pawn positions or the starting position.

        1. Precompute the shortest distance between all pairs of points (knight start and all pawns).
        2. Use DP with bitmasking to find the optimal moves.
        """

        n = len(positions)
        # All points of interest: starting position + all pawn positions
        points = [(kx, ky)] + positions
        num_points = len(points)

        # Precompute distances between all points using BFS
        # dists[i][j] is the shortest distance from points[i] to points[j]
        dists = [[0] * num_points for _ in range(num_points)]

        def get_distances(start_idx):
            sx, sy = points[start_idx]
            # BFS to find shortest path to all other points on a 50x50 board
            # Note: The knight can move outside the 50x50 board if needed, 
            # but the problem says the board is 50x50. Let's assume the board is 50x50.
            # Actually, the knight can move to any cell (x, y) where 0 <= x, y < 50.
            # Wait, the problem says "50 x 50 chessboard". Let's stick to 0-49.

            q = deque([(sx, sy, 0)])
            visited = [[-1] * 50 for _ in range(50)]
            visited[sx][sy] = 0

            while q:
                x, y, d = q.popleft()

                for dx, dy in [(2, 1), (2, -1), (-2, 1), (-2, -1), (1, 2), (1, -2), (-1, 2), (-1, -2)]:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < 50 and 0 <= ny < 50 and visited[nx][ny] == -1:
                        visited[nx][ny] = d + 1
                        q.append((nx, ny, d + 1))

            for j in range(num_points):
                px, py = points[j]
                dists[start_idx][j] = visited[px][py]

        for i in range(num_points):
            get_distances(i)

        # DP with bitmask
        # memo[(current_point_idx, mask)]
        # mask: bit i is 1 if pawn i is still on the board (pawn i is at points[i+1])
        memo = {}

        def solve(curr_idx, mask, is_alice):
            if mask == 0:
                return 0

            state = (curr_idx, mask, is_alice)
            if state in memo:
                return memo[state]

            if is_alice:
                # Alice wants to maximize
                res = -float('inf')
                for i in range(n):
                    if (mask >> i) & 1:
                        # Capture pawn i (which is at points[i+1])
                        move_dist = dists[curr_idx][i + 1]
                        res = max(res, move_dist + solve(i + 1, mask ^ (1 << i), False))
                memo[state] = res
                return res
            else:
                # Bob wants to minimize
                res = float('inf')
                for i in range(n):
                    if (mask >> i) & 1:
                        # Capture pawn i
                        move_dist = dists[curr_idx][i + 1]
                        res = min(res, move_dist + solve(i + 1, mask ^ (1 << i), True))
                memo[state] = res
                return res

        # Initial call: knight at points[0], all pawns present (mask = (1 << n) - 1), Alice's turn
        return solve(0, (1 << n) - 1, True)

