class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        """
        Finds the total number of substrings of 'word' that contain every vowel 
        ('a', 'e', 'i', 'o', 'u') at least once and exactly k consonants.

        Constraints:
        5 <= word.length <= 250
        word consists only of lowercase English letters.
        0 <= k <= word.length - 5

        Since the constraints are small (word.length <= 250), an O(N^2) approach 
        is perfectly acceptable.
        """
        n = len(word)
        vowels = {'a', 'e', 'i', 'o', 'u'}
        total_count = 0

        for i in range(n):
            vowel_counts = {'a': 0, 'e': 0, 'i': 0, 'o': 0, 'u': 0}
            vowel_set_size = 0
            consonant_count = 0

            for j in range(i, n):
                char = word[j]
                if char in vowels:
                    if vowel_counts[char] == 0:
                        vowel_set_size += 1
                    vowel_counts[char] += 1
                else:
                    consonant_count += 1

                # Check if the current substring word[i:j+1] meets the criteria
                if vowel_set_size == 5 and consonant_count == k:
                    total_count += 1

                # Optimization: if consonant_count exceeds k, we can stop the inner loop
                # because adding more characters will only increase the consonant count.
                if consonant_count > k:
                    break

        return total_count

