class Solution:
    def minOperations(self, nums: List[int]) -> int:
        n = len(nums)
        if n <= 1:
            return 0

        MAX_VAL = 1000001
        spf = list(range(MAX_VAL))
        for i in range(2, int(MAX_VAL**0.5) + 1):
            if spf[i] == i:
                for j in range(i*i, MAX_VAL, i):
                    if spf[j] == j:
                        spf[j] = i

        def get_next(x):
            if x <= 1: return x
            return spf[x]

        ops = 0
        # We must iterate backwards to ensure that we only reduce elements
        # when necessary, and we reduce them to the largest possible value
        # that is still <= the element to its right.
        # Since the only possible values for nums[i] are nums[i] and spf[nums[i]],
        # we check if nums[i] is already <= nums[i+1].
        # If not, we check if spf[nums[i]] <= nums[i+1].
        for i in range(n - 2, -1, -1):
            if nums[i] > nums[i+1]:
                next_val = get_next(nums[i])
                # If next_val is the same as nums[i], it means nums[i] is prime or 1,
                # and we cannot reduce it further to satisfy the condition.
                if next_val < nums[i] and next_val <= nums[i+1]:
                    nums[i] = next_val
                    ops += 1
                else:
                    return -1

        return ops

