class Solution:
    def minOperations(self, n: int, m: int) -> int:
        limit = 10000
        is_prime = [True] * limit
        is_prime[0] = is_prime[1] = False
        for p in range(2, int(limit**0.5) + 1):
            if is_prime[p]:
                for i in range(p * p, limit, p):
                    is_prime[i] = False

        if is_prime[n]:
            return -1

        num_digits = len(str(n))
        pq = [(n, n)]
        min_costs = {n: n}

        while pq:
            current_cost, current_n = heapq.heappop(pq)

            if current_cost > min_costs.get(current_n, float('inf')):
                continue

            if current_n == m:
                return current_cost

            s_n = str(current_n).zfill(num_digits)
            digits = [int(d) for d in s_n]

            for i in range(num_digits):
                # Increase digit i by 1
                if digits[i] < 9:
                    new_digits = digits[:]
                    new_digits[i] += 1
                    new_n = int("".join(map(str, new_digits)))
                    if not is_prime[new_n]:
                        new_cost = current_cost + new_n
                        if new_cost < min_costs.get(new_n, float('inf')):
                            min_costs[new_n] = new_cost
                            heapq.heappush(pq, (new_cost, new_n))

                # Decrease digit i by 1
                if digits[i] > 0:
                    new_digits = digits[:]
                    new_digits[i] -= 1
                    new_n = int("".join(map(str, new_digits)))
                    if not is_prime[new_n]:
                        new_cost = current_cost + new_n
                        if new_cost < min_costs.get(new_n, float('inf')):
                            min_costs[new_n] = new_cost
                            heapq.heappush(pq, (new_cost, new_n))

        return -1

