# The problem asks for the number of ways to replace '?' in a string S with '(' or ')' 
# such that the resulting string is a valid parenthesis string.
# A valid parenthesis string must satisfy:
# 1. The total number of '(' equals the total number of ')'.
# 2. For any prefix, the number of '(' is greater than or equal to the number of ')'.

def solve():
    # Read input string S
    s = sys.stdin.readline().strip()
    if not s:
        return

    n = len(s)

    # If the length is odd, it can't be a valid parenthesis string.
    if n % 2 != 0:
        print(0)
        return

    MOD = 998244353

    # dp[i][j] will be the number of ways to form a prefix of length i with a balance of j.
    # Balance j = (number of '(') - (number of ')')
    # j must always be >= 0 and <= n.

    # Using a 1D array to optimize space: dp[j] is the number of ways to have balance j.
    dp = [0] * (n + 1)
    dp[0] = 1

    for char in s:
        new_dp = [0] * (n + 1)
        if char == '(':
            # If we add '(', balance increases by 1
            for j in range(n):
                if dp[j] > 0:
                    new_dp[j+1] = dp[j]
        elif char == ')':
            # If we add ')', balance decreases by 1
            for j in range(1, n + 1):
                if dp[j] > 0:
                    new_dp[j-1] = dp[j]
        else: # char == '?'
            # We can add either '(' or ')'
            for j in range(n + 1):
                if dp[j] > 0:
                    # Add '('
                    if j + 1 <= n:
                        new_dp[j+1] = (new_dp[j+1] + dp[j]) % MOD
                    # Add ')'
                    if j - 1 >= 0:
                        new_dp[j-1] = (new_dp[j-1] + dp[j]) % MOD
        dp = new_dp

    # The answer is the number of ways to have a balance of 0 after processing all characters.
    print(dp[0])

