def solve():
    # Read all input lines and strip whitespace
    input_data = sys.stdin.read().splitlines()
    input_data = [line.strip() for line in input_data if line.strip()]

    if not input_data:
        return

    # Parse the three polyominoes
    polyominoes_raw = []
    for i in range(3):
        poly = []
        for j in range(4):
            poly.append(input_data[i*4 + j])
        polyominoes_raw.append(poly)

    # Convert each polyomino into a list of relative coordinates (dr, dc)
    # relative to its first '#' found.
    poly_coords_list = []
    for i in range(3):
        coords = []
        for r in range(4):
            for c in range(4):
                if polyominoes_raw[i][r][c] == '#':
                    coords.append((r, c))

        # Normalize coordinates so the first '#' is at (0,0)
        # Actually, it's better to just store all absolute coordinates
        # and then find all possible translations/rotations.
        poly_coords_list.append(coords)

    # Function to rotate a set of coordinates 90 degrees clockwise
    def rotate(coords):
        # (r, c) -> (c, -r)
        return [(c, -r) for r, c in coords]

    # Function to get all 4 rotations of a polyomino
    def get_rotations(coords):
        rotations = []
        current = coords
        for _ in range(4):
            # Normalize current rotation: shift so min_r=0 and min_c=0
            min_r = min(r for r, c in current)
            min_c = min(c for r, c in current)
            normalized = sorted([(r - min_r, c - min_c) for r, c in current])
            if normalized not in rotations:
                rotations.append(normalized)
            current = rotate(current)
        return rotations

    # Pre-calculate all possible rotations for each polyomino
    all_rotations = []
    for i in range(3):
        all_rotations.append(get_rotations(poly_coords_list[i]))

    # Function to check if a placement is valid
    # A placement is a list of (r, c) coordinates for each polyomino
    def check(placements):
        occupied = set()
        for p in placements:
            for r, c in p:
                if not (0 <= r < 4 and 0 <= c < 4):
                    return False
                if (r, c) in occupied:
                    return False
                occupied.add((r, c))
        return len(occupied) == 16

    # Try all combinations of rotations and translations
    # poly_idx: 0, 1, 2
    # rot_idx: 0, 1, 2, 3
    # trans_r: -3 to 3, trans_c: -3 to 3

