import sys

# The problem asks for the minimum weight of a walk that visits all N vertices at least once.
# N is small (up to 20). This suggests a dynamic programming approach with bitmask.
# A walk can visit vertices multiple times. This is equivalent to finding a path in a 
# complete graph where the edge weight between u and v is the shortest path distance from u to v.
# Since there are no negative cycles, the shortest path distance is well-defined.

def solve():
    # Read N and M
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    M = int(input_data[1])

    # Initialize distance matrix with infinity
    INF = float('inf')
    dist = [[INF] * N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0

    idx = 2
    for _ in range(M):
        u = int(input_data[idx]) - 1
        v = int(input_data[idx+1]) - 1
        w = int(input_data[idx+2])
        dist[u][v] = min(dist[u][v], w)
        idx += 3

    # Floyd-Warshall algorithm to find all-pairs shortest paths
    for k in range(N):
        for i in range(N):
            if dist[i][k] == INF:
                continue
            for j in range(N):
                if dist[k][j] != INF:
                    if dist[i][j] > dist[i][k] + dist[k][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

    # DP state: dp[mask][last_vertex]
    # mask: bitmask of visited vertices
    # last_vertex: the last vertex visited in the walk
    # dp[mask][i] = minimum weight to visit vertices in mask, ending at vertex i

    num_masks = 1 << N
    dp = [[INF] * N for _ in range(num_masks)]

    # Base case: starting at any vertex i
    for i in range(N):
        dp[1 << i][i] = 0

    # DP transitions
    for mask in range(1, num_masks):
        for i in range(N):
            if dp[mask][i] == INF:
                continue

            # Try moving to a vertex j that hasn't been visited in the mask
            # or even if it has been visited, but we are looking for a walk.
            # Actually, the shortest path distance already accounts for visiting 
            # intermediate vertices. So we only need to transition to a new vertex.
            for j in range(N):
                if not (mask & (1 << j)):
                    if dist[i][j] != INF:
                        new_mask = mask | (1 << j)
                        if dp[new_mask][j] > dp[mask][i] + dist[i][j]:
                            dp[new_mask][j] = dp[mask][i] + dist[i][j]

    # The answer is the minimum dp[(1 << N) - 1][i] for all i
    ans = INF
    final_mask = (1 << N) - 1
    for i in range(N):
        if dp[final_mask][i] < ans:
            ans = dp[final_mask][i]

    if ans == INF:
        print("No")
    else:
        print(int(ans))

