        (0, 3, 6), (1, 4, 7), (2, 5, 8), # Cols
        (0, 4, 8), (2, 4, 6)             # Diagonals
    ]

    memo = {}

    def check_win(grid, color):
        # color: 1 for Takahashi (Red), 2 for Aoki (Blue)
        for line in lines:
            if grid[line[0]] == color and grid[line[1]] == color and grid[line[2]] == color:
                return True
        return False

    def get_winner_refined(grid):
        if grid in memo:
            return memo[grid]

        # Determine whose turn it is by counting non-zero cells
        non_zero_count = 0
        for x in grid:
            if x != 0:
                non_zero_count += 1

        # Takahashi moves on 0, 2, 4, 6, 8 non-zero cells
        # Aoki moves on 1, 3, 5, 7 non-zero cells
        turn = 0 if non_zero_count % 2 == 0 else 1

        # Check if the PREVIOUS player won
        if turn == 0: # Takahashi's turn, Aoki just moved
            if check_win(grid, 2):
                memo[grid] = -1
                return -1
        else: # Aoki's turn, Takahashi just moved
            if check_win(grid, 1):
                memo[grid] = 1
                return 1

