            score_t = 0
            score_a = 0
            for i in range(9):
                if grid[i] == 1:
                    score_t += flat_A[i]
                elif grid[i] == 2:
                    score_a += flat_A[i]
            res = 1 if score_t > score_a else -1
            memo[grid] = res
            return res

