            best_val = -2
            for i in range(9):
                if grid[i] == 0:
                    # Create new grid tuple
                    new_grid_list = list(grid)
                    new_grid_list[i] = 1
                    res = get_winner_refined(tuple(new_grid_list))
                    if res > best_val:
                        best_val = res
                    if best_val == 1:
