import sys

def solve():
    # Read the input string from stdin
    s = sys.stdin.read().strip()

    # Condition 1: |T| must be even
    n = len(s)
    if n % 2 != 0:
        print("No")
        return

    # Condition 2: For each i from 1 to |T|/2, the (2i-1)-th and 2i-th characters are equal.
    # In 0-indexed terms, s[2*i] and s[2*i + 1] must be equal for i in range(0, n//2).
    for i in range(0, n, 2):
        if s[i] != s[i+1]:
            print("No")
            return

    # Condition 3: Each character appears in T exactly zero or two times.
    # This means every character that appears in the string must appear exactly twice.
    char_counts = {}
    for char in s:
        char_counts[char] = char_counts.get(char, 0) + 1

    for char in char_counts:
        if char_counts[char] != 2:
            print("No")
            return

    # If all conditions are met
    print("Yes")

if __name__ == "__main__":
    solve()

